import pymupdf
files = ["Integrity/Procedures/Merrowfield_UT_Procedure_Rev3.pdf","Integrity/Procedures/Ashgrove_UT_Procedure_Rev2.pdf",
         "Integrity/Tanks/T-02-003/Inspection_Report_T-02-003.pdf","Integrity/Tanks/T-02-003/FFS_Assessment_T-02-003.pdf",
         "Integrity/Surveys/FieldSheets/AG-FLD-2025-0917-C1.pdf","Integrity/Tanks/T-02-003/Process_Data_T-02-003.pdf"]
for fn in files:
    doc = pymupdf.open(fn)
    print("=====", fn, "pages", len(doc), "meta", doc.metadata)
    for pno, page in enumerate(doc):
        annots = list(page.annots() or [])
        if annots:
            for a in annots: print("  ANNOT p", pno+1, a.type, a.info, a.rect)
        # look for text with white color or tiny font or outside page
        d = page.get_text("dict")
        for b in d["blocks"]:
            for l in b.get("lines", []):
                for s in l["spans"]:
                    col = s["color"]; size = s["size"]; bbox = s["bbox"]
                    txt = s["text"].strip()
                    if not txt: continue
                    outside = bbox[0] > page.rect.width or bbox[1] > page.rect.height or bbox[2] < 0 or bbox[3] < 0
                    if col == 0xFFFFFF or size < 4 or outside:
                        print(f"  HIDDEN? p{pno+1} color={col:06x} size={size:.1f} bbox={tuple(round(x) for x in bbox)} :: {txt[:150]}")
        # drawings that might be white boxes covering text
        for dr in page.get_drawings():
            if dr.get("fill") == (1.0,1.0,1.0) and dr["rect"].width > 50 and dr["rect"].height > 8:
                # check text underneath
                under = page.get_textbox(dr["rect"]).strip()
                if under:
                    print(f"  WHITE BOX p{pno+1} {tuple(round(x) for x in dr['rect'])} covers text: {under[:200]}")
EOF

