import openpyxl, datetime as dt
mf = openpyxl.load_workbook("Merrowfield_UT_Survey_2025.xlsx", data_only=True)["T-02-003"]
ag = openpyxl.load_workbook("Ashgrove_UT_Survey_2025.xlsx", data_only=True)["T-02-003"]
M = {}; A = {}
for r in mf.iter_rows(min_row=10, max_row=45, values_only=True):
    if r[0]: M[r[0]] = dict(course=r[1], q=r[2], el=r[3], rmin=r[7], bl=r[8])
for r in ag.iter_rows(min_row=10, max_row=45, values_only=True):
    if r[0]: A[r[0]] = dict(course=r[1], q=r[2], el=r[3], rmin=r[8])
OFF = 12
print("== Course 1, common datum (in above bottom-of-shell weld) ==")
for q in "NESW":
    print(f"-- {q}")
    rows = []
    for k,v in M.items():
        if v['course']==1 and v['q']==q: rows.append((v['el']+OFF, 'MF', k, v['bl'], v['rmin']))
    for k,v in A.items():
        if v['course']==1 and v['q']==q: rows.append((v['el'], 'AG', k, None, v['rmin']))
    for e in sorted(set(r[0] for r in rows)):
        mfr = [r for r in rows if r[0]==e and r[1]=='MF']; agr=[r for r in rows if r[0]==e and r[1]=='AG']
        s = f"  {e:>3} in: "
        if mfr: s += f"MF {mfr[0][2]:<8} CB21={mfr[0][3]:.3f} MF25={mfr[0][4]:.3f} d21-25={mfr[0][3]-mfr[0][4]:.3f} rate={(mfr[0][3]-mfr[0][4])/4.0*1000:.2f}mpy  "
        if agr: s += f"AG {agr[0][2]:<8} AG25={agr[0][4]:.3f}"
        if mfr and agr: s += f"  dMF->AG={mfr[0][4]-agr[0][4]:.3f}"
        print(s)
# naive step at label C1-x-6
print("== Naive same-label pairs C1-x-6 ==")
for q in "NESW":
    print(q, M[f"C1-{q}-6"]['rmin'], A[f"C1-{q}-6"]['rmin'], round(M[f"C1-{q}-6"]['rmin']-A[f"C1-{q}-6"]['rmin'],3))
# AG 24 vs MF midpoint of 6 & 18 (above TOR) = 18 & 30 above weld -> midpoint 24
print("== AG C1-x-24 vs midpoint of MF C1-x-6 and C1-x-18 ==")
for q in "NESW":
    mid=(M[f"C1-{q}-6"]['rmin']+M[f"C1-{q}-18"]['rmin'])/2
    print(q, "AG24=",A[f"C1-{q}-24"]['rmin'], "MFmid=",round(mid,4), "diff=",round(mid-A[f"C1-{q}-24"]['rmin'],4))
# upper courses
print("== Courses 2-5 ==")
for c in range(2,6):
    mfv=[(k,v['bl'],v['rmin'],round(v['bl']-v['rmin'],3)) for k,v in M.items() if v['course']==c]
    agv=[(k,v['rmin']) for k,v in A.items() if v['course']==c]
